DO $$ BEGIN
  IF (SELECT count(*) FROM public.product_types) <> 660 OR (SELECT count(*) FROM public.product_type_rules) <> 686 THEN
    RAISE EXCEPTION 'Rodzaje: oczekiwano 660 rodzajów i 686 reguł (z pilotem) - brak podkategorii albo pilota w bazie.';
  END IF;
END $$;

ALTER TABLE public.products DISABLE TRIGGER trg_products_updated_at;
SELECT public.refresh_product_types();
ALTER TABLE public.products ENABLE TRIGGER trg_products_updated_at;

NOTIFY pgrst, 'reload schema';
